import{z as A,x as B,o as t,c as d,q as r,j as s,D as e,d as l,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"RLS 三角","description":"","frontmatter":{"title":"RLS 三角","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/rls-tradeoff.md","filePath":"litho/rls-tradeoff.md","lastUpdated":1791413859000}'),p={name:"litho/rls-tradeoff.md"};function h(R,a,m,f,u,L){const i=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="rls-三角" tabindex="-1">RLS 三角 <a class="header-anchor" href="#rls-三角" aria-label="Permalink to &quot;RLS 三角&quot;">​</a></h1><div class="epigraph"><p>分辨率要核小，LER 要核大或光子多，灵敏度要光子少：三个顶点不能同时钉在最优。胶与剂量的选择是在三角形里挪点。</p><footer>—— 据 Gallatin / Bristol 对 resolution–LER–sensitivity 权衡的公开论述；Naulleau 的随机实验语法</footer></div><p><a href="/litho/stochastics-vs-nils">上一课</a>把光学 NILS 写成随机增益。缺口是材料侧不能再假装「更敏、更锐、更光」可兼得：这就是 RLS 三角。主干 <a href="/litho/euv-resist">EUV 胶</a> 已经点过名字。本课把它接到本课程的核、计数与 Z 因子上。均值 E–D 窗外还要切随机窗，留给<a href="/litho/stochastic-process-window">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Resolution：有效模糊（电子核 + 酸核 + 显影）必须短于半节距预算。LER：同一套涨落，核短则高频毛、光子少则幅度大。Sensitivity：\\(E_\\mathrm{size}\\) 低则扫描快、源功率够用，但 \\(N\\) 小、尾肥。加淬灭、降 PEB：核短、分辨率好、灵敏度差、有时 LER 高频升。加剂量：LER 与缺陷降，灵敏度这项「变差」（从产能看）。加吸收 / 金属胶：同样 \\(E\\) 下 \\(N\\) 升，但团簇与沾污换一套 R。</p><p><span class="marginnote">术语翻译：RLS 是 Resolution（分辨率）、LER（线边缘粗糙度）、Sensitivity（灵敏度）三个词的缩写。可以记成「又细又滑又快」：图形要细（R）、边缘要滑（L）、曝光要快（S）——三样都要，光子账单只够付两样。</span></p><p>缺口不是再讲 CAR 循环，而是：后课改配方时必须声明挪的是哪一角，禁止只报「更敏」或只报「LER 3 nm」。Z 因子是三角上的一个标量投影，投影方向随定义变。</p><h3 id="光学不取消三角" tabindex="-1">光学不取消三角 <a class="header-anchor" href="#光学不取消三角" aria-label="Permalink to &quot;光学不取消三角&quot;">​</a></h3><p>NILS 升高，同样材料点的 LER 与缺陷改善，看起来三角缩小。目标 CD 若跟着缩，R 角更紧。RET 是在光学上买裕量，不是删除材料三角。<a href="/litho/pag-quencher">pag-quencher</a> 的一对加载是 R 与 S 之间最常用的配方轴。</p><p><span class="marginnote">不要把三角画成等边必然。有的胶族 L 角被团聚钉死，加剂量也降不到地板以下。那是化学地板，不是几何课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画图：横轴 \\(E_\\mathrm{size}\\)，纵轴 LER，参数是模糊或节距；另一张看缺陷率。资格：同一节距、同一 NILS 协议下比胶，否则在比光学。改一个旋钮（PEB、负载、胶厚、剂量）必须同时报 R、L、S 三个读出——CD 能否分辩、谱或 \\(3\\sigma\\)、清场/到尺寸剂量。</p><p>与<a href="/litho/acid-diffusion-lwr">酸扩散</a>：\\(\\ell\\) 是三角里明确的核旋钮。与二次电子核：EUV 上即使 \\(\\ell\\to 0\\)，R 角仍被 \\(G_e\\) 卡住。</p>',13)),(t(),s(n,null,{default:e(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%88%86%E8%BE%A8%E7%8E%87%3A%20%E6%A0%B8%E8%A6%81%E7%9F%AD%22%5D%20--%3E%20TRI%5B%22RLS%20%E5%B7%A5%E4%BD%9C%E7%82%B9%22%5D%0A%20%20L%5B%22LER%3A%20%E6%B6%A8%E8%90%BD%E8%A6%81%E5%B0%8F%22%5D%20--%3E%20TRI%0A%20%20S%5B%22%E7%81%B5%E6%95%8F%E5%BA%A6%3A%20E%20%E8%A6%81%E4%BD%8E%22%5D%20--%3E%20TRI%0A%20%20TRI%20--%3E%20PW%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%9A%8F%E6%9C%BA%E7%AA%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"信息论口语：更少的光子要在更小的体积里做更确定的决定，统计不允许。模糊把体积做大，确定些，边糊。化学增益把一个光子变成许多酸，灵敏度好，但把出生位置的随机放大——Ito 的增益在 DUV 买产能，在 EUV 薄胶上把 L 角推出来。金属氧化物提高吸收，是在 S 角用截面付钱，而不是用增益付钱，L 角换成团簇。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：化学增益像请人把一句话扩写成十句——信息量大、省得听清原文（灵敏度好），但转述者自己拿不准的地方也被放大成十处含糊（光子落点的随机被同比例放大成边缘毛刺）。")],-1)),(t(),s(n,null,{default:e(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20PH%5B%22%E4%B8%80%E4%B8%AA%20EUV%20%E5%85%89%E5%AD%90%E8%A2%AB%E5%90%B8%E6%94%B6%22%5D%20--%3E%20GE%5B%22%E5%8C%96%E5%AD%A6%E5%A2%9E%E7%9B%8A%E6%94%BE%E5%A4%A7%E6%88%90%E8%AE%B8%E5%A4%9A%E9%85%B8%22%5D%0A%20%20GE%20--%3E%20SENS%5B%22%E5%89%82%E9%87%8F%E5%8F%AF%E4%BB%A5%E4%BD%8E%3A%20S%20%E8%A7%92%E5%8F%98%E5%A5%BD%22%5D%0A%20%20GE%20--%3E%20RAND%5B%22%E5%87%BA%E7%94%9F%E4%BD%8D%E7%BD%AE%E7%9A%84%E9%9A%8F%E6%9C%BA%E4%B8%80%E8%B5%B7%E6%94%BE%E5%A4%A7%22%5D%0A%20%20RAND%20--%3E%20LER%5B%22%E8%BE%B9%E7%BC%98%E6%AF%9B%E5%88%BA%E5%8F%98%E5%A4%9A%3A%20L%20%E8%A7%92%E5%8F%98%E5%B7%AE%22%5D%0A%20%20PH%20--%3E%20VOL%5B%22%E6%A8%A1%E7%B3%8A%E6%8A%8A%E5%8F%8D%E5%BA%94%E4%BD%93%E7%A7%AF%E5%81%9A%E5%A4%A7%22%5D%0A%20%20VOL%20--%3E%20RAND%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>Gallatin 把 LER 写成模糊与剂量的函数，定性就是这个三角。定量预因子随胶变，本课不抄某一拟合当定律。</p><p><span class="marginnote">数字实例：剂量从 30 提到 \\(60\\ \\mathrm{mJ/cm^2}\\)，吸收光子数 \\(N\\) 翻倍，泊松涨落的相对幅度 \\(\\sim 1/\\sqrt{N}\\) 只降约三成——LER 是平方根级别的慢改善，产能却直接砍半。这就是「加剂量买 L 角」越来越不划算的原因。</span></p><p><span class="marginnote">干法显影与 MOR 会改三角的材料边，不删除顶点。后两课换胶族，三角语言保留。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某篇 SPIE 的「最佳模糊 5 nm」写成所有层。不重导瑞利 \\(k_1\\) 来当 R 的定义——R 这里是胶核与半节距预算，不是镜头公式。下一课把三角上的点放进剂量–焦平面：有的点平均 CD 窗还在，随机窗已经关上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RLS：核短、光子多、剂量低不能同时最优。</li><li>改 PEB / 淬灭 / 吸收 / 剂量都是在三角上挪点，必须三报。</li><li>NILS 改光学增益，不删除三角；目标缩则 R 更紧。</li><li>Z 因子是投影，不是第四个独立物理。</li><li>出处：Gallatin / Bristol RLS；Naulleau；主干 <a href="/litho/euv-resist">euv-resist</a>。</li></ul>',7))])}const c=A(p,[["render",h]]);export{S as __pageData,c as default};
